package com.ezylang.evalex.parser;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;
import com.ezylang.evalex.config.ExpressionConfiguration;
import com.ezylang.evalex.operators.OperatorIfc;
import org.junit.Test;
import org.mockito.Mockito;
import java.util.List;

public class TokenizerTest {

    @Test
    public void parseNullExpressionTest() {
        ExpressionConfiguration config = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer(null, config);
        Throwable thrown = catchThrowable(tokenizer::parse);
        assertThat(thrown).isInstanceOf(ParseException.class);
    }

    @Test
    public void parseEmptyExpressionTest() throws ParseException {
        ExpressionConfiguration config = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("", config);
        List<Token> tokens = tokenizer.parse();
        assertThat(tokens).isEmpty();
    }

    @Test
    public void parseValidExpressionTest() throws ParseException {
        ExpressionConfiguration config = new ExpressionConfiguration();
        OperatorIfc mockOperator = Mockito.mock(OperatorIfc.class);
        Mockito.when(mockOperator.is("ADDITION")).thenReturn(true);
        config.getOperators().insert(mockOperator);
        Tokenizer tokenizer = new Tokenizer("1+2", config);
        List<Token> tokens = tokenizer.parse();
        assertThat(tokens).hasSize(3);
    }

    @Test
    public void parseInvalidExpressionTest() {
        ExpressionConfiguration config = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("1++2", config);
        Throwable thrown = catchThrowable(tokenizer::parse);
        assertThat(thrown).isInstanceOf(ParseException.class);
    }

    @Test
    public void parseStringLiteralValidTest() throws ParseException {
        ExpressionConfiguration config = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("\"Hello, World!\"", config);
        Token token = tokenizer.parseStringLiteral();
        assertThat(token.getValue()).isEqualTo("Hello, World!");
    }

    @Test
    public void parseStringLiteralInvalidTest() {
        ExpressionConfiguration config = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("\"Hello, World!", config);
        Throwable thrown = catchThrowable(tokenizer::parseStringLiteral);
        assertThat(thrown).isInstanceOf(ParseException.class);
    }
}
